-- 603: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 10 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_603_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_603_guard;
INSERT INTO _migration_603_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_037' AND NOT (q.topic_id IS 'topic_igcse_chem_electrolysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'During electrolysis, which electrode is the anode?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The negative electrode","B. The electrode where reduction occurs","C. The electrode at which metals are always deposited","D. The positive electrode"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The anode is defined as the positive electrode, where anions are attracted and oxidation takes place. (The negative electrode is the cathode; reduction occurs at the cathode; metals deposit at the cathode, not the anode.) Therefore the correct answer is D: The positive electrode.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_037' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_603_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_038' AND NOT (q.topic_id IS 'topic_igcse_chem_electrolysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must an ionic compound be molten, or dissolved in water, before it can be electrolysed?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. So that its ions are free to move and carry the electric current.","B. So that electrons can flow through the liquid.","C. To increase the voltage of the power supply.","D. To prevent the compound reacting with the electrodes."]' AND q.correct_answer IS 'A' AND q.explanation IS 'In the solid lattice the ions are locked in fixed positions. Melting or dissolving frees the ions to move to the electrodes, which is how the current is carried through the electrolyte. (Electrolytes conduct by moving ions, not electrons; the voltage comes from the supply.) Therefore the correct answer is A: So that its ions are free to move and carry the electric current..' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_038' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_603_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_039' AND NOT (q.topic_id IS 'topic_igcse_chem_electrolysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which material is commonly used to make inert electrodes for electrolysis?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Copper","B. Graphite","C. Iron","D. Aluminium"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Graphite (and platinum) conduct electricity yet are unreactive, so they do not take part in the electrolysis — they are inert. (Copper, iron and aluminium are active electrodes that can themselves oxidise and dissolve at the anode.) Therefore the correct answer is B: Graphite.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_039' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_603_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_040' AND NOT (q.topic_id IS 'topic_igcse_chem_electrolysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Concentrated aqueous sodium chloride is electrolysed using inert electrodes. What are the products at the cathode and at the anode?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Sodium at the cathode and chlorine at the anode.","B. Hydrogen at the cathode and oxygen at the anode.","C. Hydrogen at the cathode and chlorine at the anode.","D. Chlorine at the cathode and hydrogen at the anode."]' AND q.correct_answer IS 'C' AND q.explanation IS 'At the cathode hydrogen is discharged because hydrogen is less reactive than sodium: 2H⁺ + 2e⁻ → H₂. At the anode, the high chloride concentration means Cl⁻ is discharged rather than OH⁻: 2Cl⁻ → Cl₂ + 2e⁻. (Sodium is never discharged from aqueous solution; oxygen forms at the anode only when the chloride is dilute; the products are never swapped between electrodes.) Therefore the correct answer is C: Hydrogen at the cathode and chlorine at the anode..' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Predict' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_040' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_037', 'topic_igcse_chem_electrolysis', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'During electrolysis, which electrode is the anode?', 'multiple_choice', NULL, '["A. The negative electrode","B. The electrode where reduction occurs","C. The electrode at which metals are always deposited","D. The positive electrode"]', 'D', 'The anode is defined as the positive electrode, where anions are attracted and oxidation takes place. (The negative electrode is the cathode; reduction occurs at the cathode; metals deposit at the cathode, not the anode.) Therefore the correct answer is D: The positive electrode.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge');
