INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_040', 'topic_igcse_chem_electrolysis', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Concentrated aqueous sodium chloride is electrolysed using inert electrodes. What are the products at the cathode and at the anode?', 'multiple_choice', NULL, '["A. Sodium at the cathode and chlorine at the anode.","B. Hydrogen at the cathode and oxygen at the anode.","C. Hydrogen at the cathode and chlorine at the anode.","D. Chlorine at the cathode and hydrogen at the anode."]', 'C', 'At the cathode hydrogen is discharged because hydrogen is less reactive than sodium: 2H⁺ + 2e⁻ → H₂. At the anode, the high chloride concentration means Cl⁻ is discharged rather than OH⁻: 2Cl⁻ → Cl₂ + 2e⁻. (Sodium is never discharged from aqueous solution; oxygen forms at the anode only when the chloride is dilute; the products are never swapped between electrodes.) Therefore the correct answer is C: Hydrogen at the cathode and chlorine at the anode..', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Predict', 'AO3', NULL, NULL, 'board_cambridge');
